/**
 * The shared state store, where the vendored webhook engine
 * (`./webhook/registry.ts`) imports it from: `../state-store.js` relative to
 * `webhook/`. The one copy in this tree is `src/state-store.ts`, generated by
 * `npm run statestore:sync`; this file only re-exports it, so the engine stays
 * byte-identical to its source and this tree keeps one GCS client.
 */
export * from "../state-store.js";
